insert into tap_results select lives_ok($$select public.agri_command('save_credit_client',pg_temp.policy())$$,'Owner approves client');
insert into tap_results select is(public.agri_command('save_credit_client',pg_temp.policy())->>'duplicate','true','Client retry preserves original request');
insert into saved values('sale',pg_temp.sale());
insert into tap_results select lives_ok($$select public.agri_command('record_credit_sale',(select data from saved where name='sale'))$$,'Credit sale saves stock, down payment and debt atomically');
insert into tap_results select is(pg_temp.book()->>'outstanding','80000','Only unpaid amount becomes receivable');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(902)||'{"expectedDueOn":"2020-01-01"}')$$,'P0001','The issue date changed. Review the due date and manual invoice again','A changed issue date cannot silently change the agreed due date');
insert into tap_results select is(pg_temp.book()#>>'{invoices,0,dueOn}',((now() at time zone 'Asia/Manila')::date+60)::text,'Net 60 adds calendar days');
insert into tap_results select is(public.agri_command('record_credit_sale',(select data from saved where name='sale'))->>'duplicate','true','Lost sale response retries without stock or cash duplication');
